function keepAtMostTwice(nums: number[]): void {
  const n = nums.length;
  let i = 2;
  while (i < nums.length) {
    if (nums[i] === nums[i - 1] && nums[i] === nums[i - 2]) nums.splice(i, 1);
    else i++;
  }
  // restore the original length; the tail is ignored
  while (nums.length < n) nums.push(nums[nums.length - 1]);
}

