class Solution:
    def keepAtMostTwice(self, nums: List[int]) -> None:
        n = len(nums)
        i = 2
        while i < len(nums):
            if nums[i] == nums[i - 1] == nums[i - 2]:
                del nums[i]
            else:
                i += 1
        # restore the original length; the tail is ignored
        while len(nums) < n:
            nums.append(nums[-1])

